export interface Bill {
  totalCents: number;
  people: number;
  tipPercent?: number;
}

/**
 * Splits a bill between people, in cents, with an optional tip. The shares always add up to the
 * total: when it doesn't divide evenly, the first people pay one cent more.
 */
export function split({ totalCents, people, tipPercent = 0 }: Bill): number[] {
  if (!Number.isInteger(totalCents) || totalCents < 0) {
    throw new RangeError("totalCents must be a whole number of cents, 0 or more");
  }
  if (!Number.isInteger(people) || people < 1) {
    throw new RangeError("people must be a whole number, 1 or more");
  }
  if (!Number.isInteger(tipPercent) || tipPercent < 0 || tipPercent > 100) {
    throw new RangeError("tipPercent must be a whole number from 0 to 100");
  }
  const total = totalCents + Math.round((totalCents * tipPercent) / 100);
  const base = Math.floor(total / people);
  const remainder = total - base * people;
  return Array.from({ length: people }, (_, i) => base + (i < remainder ? 1 : 0));
}

