import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { split } from "./split.ts";

describe("split", () => {
  it("divides an even bill equally", () => {
    assert.deepEqual(split({ totalCents: 3000, people: 3 }), [1000, 1000, 1000]);
  });

  it("adds a tip before splitting", () => {
    assert.deepEqual(split({ totalCents: 1000, people: 3, tipPercent: 10 }), [367, 367, 366]);
  });
});
